199: function renderAttachmentList(){const host=$('attachmentList'),max=perks.gunsmith?10:3;host.innerHTML=attachmentSlots.map(slot=>{const selected=config[slot.id],used=attachmentCount(),isDefault=selected===defaultConfig[slot.id];return `<div class="attachment-row"><div class="attachment-name"><span>${slot.name}</span><small>${slot.id==='finish'?'COSMETIC':'SLOT '+String(attachmentSlots.indexOf(slot)+1).padStart(2,'0')}</small></div><div class="attachment-options" data-slot="${slot.id}">${slot.options.map(([value,label])=>{const adds=value!==defaultConfig[slot.id]&&!isDefault,blocked=!isDefault&&value!==selected&&used>=max&&value!==defaultConfig[slot.id];return `<button class="attach-option${selected===value?' active':''}" data-value="${value}" ${blocked?'disabled':''}>${label}</button>`}).join('')}</div></div>`}).join('');$('attachmentCount').textContent=`${attachmentCount()} / ${max} FITTED`;host.querySelectorAll('.attachment-options button').forEach(btn=>btn.onclick=()=>{const group=btn.closest('[data-slot]'),id=group.dataset.slot,value=btn.dataset.value;if(value!==defaultConfig[id]&&config[id]===defaultConfig[id]&&attachmentCount()>=max)return;config[id]=value;renderAttachmentList();updatePreview();if(weaponRig&&currentWeapon===selectedWeapon)buildViewWeapon()})}
