function switchLoadoutSlot(slot){if(slot<0||slot>=weaponSlots.length||weaponSlots[slot]===null||weaponSlots[slot]===undefined||slot===1&&!perks.overkill)return;const next=weaponSlots[slot];if(next===currentWeapon&&slot===currentSlot)return;saveWeaponAmmo(currentWeapon);currentSlot=slot;currentWeapon=next;config=weaponConfigs[currentWeapon];loadWeaponAmmo(currentWeapon);reloading=false;buildViewWeapon();weaponRig.position.y=-.48;weaponReadyAt=performance.now()+(perks.quickdraw?80:190);setTimeout(()=>{if(weaponRig)weaponRig.position.y=weaponRig.userData.baseY},perks.quickdraw?80:190);updateWeaponHud();showToast(`${slot===1?'OVERKILL':'LOADOUT'} — ${weapons[next].name}`)}
function magazineCapacity(w,c=config){return Math.round(w.mag*(c.magazine==='extended'?1.4:1))}
function reloadDuration(w,c=config){return w.reload*(c.magazine==='fast'?.72:1)*(perks.quickdraw?.75:1)}
function loadWeaponAmmo(index){const state=ammoStates[index],capacity=magazineCapacity(weapons[index],weaponConfigs[index]);magAmmo=Math.min(state.mag,capacity);reserveAmmo=state.reserve;state.mag=magAmmo}
function saveWeaponAmmo(index=currentWeapon){if(!ammoStates[index])return;ammoStates[index].mag=magAmmo;ammoStates[index].reserve=reserveAmmo}

