+function reload(){const w=weapons[currentWeapon],capacity=magazineCapacity(w,config);if(reloading||magAmmo>=capacity||reserveAmmo<=0)return;activeReloadDuration=reloadDuration(w,config);reloading=true;reloadEnd=performance.now()+activeReloadDuration*1000;showToast('RELOADING…');weaponRig?.position.set(.35,-.42,-.65)}
 function fireWeapon(){if(!gameActive||paused||finished||!weaponRig)return;const now=performance.now(),w=weapons[currentWeapon];if(now-lastShot<1000/w.rate)return;if(reloading){if(now<reloadEnd)return;finishReload()}if(magAmmo<=0){reload();return}lastShot=now;magAmmo--;shotsFired++;updateWeaponHud();weaponRig.userData.recoil=.095;weaponRig.rotation.x=-.04;const cameraDir=new THREE.Vector3();camera.getWorldDirection(cameraDir);const spread=w.spread*(config.optic==='precision'?.46:config.optic==='reflex'?.78:1)*(config.barrel==='compensator'?.77:1);cameraDir.x+=(Math.random()-.5)*spread;cameraDir.y+=(Math.random()-.5)*spread;cameraDir.z+=(Math.random()-.5)*spread;cameraDir.normalize();raycaster.set(camera.getWorldPosition(new THREE.Vector3()),cameraDir);const targets=bots.filter(b=>!b.dead).flatMap(b=>b.parts);const hit=raycaster.intersectObjects([...targets,...obstacles],false)[0];let end=raycaster.ray.origin.clone().add(cameraDir.clone().multiplyScalar(70));if(hit){end.copy(hit.point);if(hit.object.userData.bot){const bot=hit.object.userData.bot;const head=hit.object.position.y>1.55;const attachment=config.barrel==='compensator'?1.04:1;bot.hp-=w.damage*attachment*(head?1.55:1);bot.hitFlash=.11;shotsHit++;showHitmarker();if(bot.hp<=0)killBot(bot);else{hit.object.material.emissive?.setHex(0x581e11);setTimeout(()=>{if(hit.object.material.emissive)hit.object.material.emissive.setHex(0)},100)}}}
   makeTracer(camera.getWorldPosition(new THREE.Vector3()),end,w.color);const muzzle=new THREE.PointLight(w.color,2.4,4);muzzle.position.copy(camera.position);muzzle.position.add(cameraDir.clone().multiplyScalar(.75));camera.add(muzzle);setTimeout(()=>camera.remove(muzzle),45);$('crosshair').style.transform='translate(-50%,-50%) scale(1.35)';setTimeout(()=>$('crosshair').style.transform='translate(-50%,-50%) scale(1)',70);if(magAmmo===0)showToast('MAGAZINE EMPTY — PRESS R');
 }
 function finishReload(){const w=weapons[currentWeapon],needed=w.mag-magAmmo,take=Math.min(needed,reserveAmmo);magAmmo+=take;reserveAmmo-=take;reloading=false;weaponRig?.position.set(.35,-.32,-.65);updateWeaponHud()}

