 .weapon-slot-label{font-size:6px;letter-spacing:0}
 .weapon-slot small{right:4px;top:5px;font-size:6px}
 .attachments,.perks-view{padding-top:9px}
 .attachments .section-label,.perks-view .section-label{font-size:7px;padding-right:2px}
 .attachments .section-label span,.perks-view .section-label span{font-size:6px}
 .attachment-row{display:block;padding:5px 0;min-height:51px}
 .attachment-name{width:100%;height:13px;font-size:6px}
 .attachment-name small{font-size:5px}
 .attachment-options{width:100%;gap:3px}
