const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
let targets;
for (let i=0;i<30;i++) { try { targets=await (await fetch('http://127.0.0.1:9223/json')).json(); if (targets.length) break; } catch {} await sleep(200); }
const target=targets.find(item=>item.type==='page');
const ws=new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve,reject)=>{ws.onopen=resolve;ws.onerror=reject});
let id=0; const pending=new Map();
ws.onmessage=event=>{const message=JSON.parse(event.data);if(message.id&&pending.has(message.id)){pending.get(message.id)(message);pending.delete(message.id)}else if(message.method==='Runtime.exceptionThrown')console.log('EXCEPTION',message.params.exceptionDetails.text)};
const call=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}))});
const evaluate=async expression=>(await call('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true})).result.result.value;
await call('Page.enable');await call('Runtime.enable');await call('Page.navigate',{url:'http://127.0.0.1:8765/'});await sleep(6000);
await evaluate(`document.querySelector('#loadoutBtn').click();true`);await sleep(300);
const result=await evaluate(`(()=>{
 document.querySelector('[data-tab="perks"]').click();
 document.querySelector('[data-perk="gunsmith"]').click();
 document.querySelector('[data-tab="attachments"]').click();
 const group=id=>document.querySelector('[data-slot="'+id+'"]');
 const choose=(slot,value)=>group(slot).querySelector('[data-value="'+value+'"]').click();
 choose('optic','reflex');choose('barrel','long');choose('muzzle','compensator');
 const before=document.querySelector('#attachmentCount').textContent;
 const addBlocked=group('stock').querySelector('[data-value="tactical"]').disabled;
 const replaceEnabled=!group('optic').querySelector('[data-value="precision"]').disabled;
 choose('optic','precision');choose('finish','arctic');
 const after=document.querySelector('#attachmentCount').textContent;
 const finish=document.querySelector('[data-slot="finish"] [data-value="arctic"]').classList.contains('active');
 return {before,addBlocked,replaceEnabled,after,finish};
})()`);
console.log('ATTACHMENT CAP',JSON.stringify(result));
if(!result.addBlocked||!result.replaceEnabled||result.before!=='3 / 3 FITTED'||result.after!=='3 / 3 FITTED'||!result.finish)process.exitCode=1;
ws.close();

