+
+/* Loadout configuration */
+.loadout-tabs{display:flex;gap:6px;margin-top:12px;border-bottom:1px solid var(--line)}
+.loadout-tab{flex:1;min-height:36px;padding:0 12px;text-align:left;background:transparent;border:1px solid transparent;border-bottom:0;color:#7f8d82;font:8px var(--mono);letter-spacing:.1em;cursor:pointer}
+.loadout-tab span{float:right;color:#718078;font-size:7px}
+.loadout-tab:hover,.loadout-tab.active{color:var(--acid);background:rgba(182,239,103,.055);border-color:rgba(182,239,103,.25)}
+.loadout-tab.active span{color:#a7c77f}
+.weapon-slots{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:7px;margin:10px 0 0}
+.weapon-slot{position:relative;min-width:0;min-height:53px;padding:7px 29px 7px 9px;text-align:left;background:rgba(255,255,255,.018);border:1px solid rgba(220,240,220,.12);cursor:pointer;transition:border-color .15s,background .15s}
+.weapon-slot:hover:not(:disabled),.weapon-slot.active{border-color:rgba(182,239,103,.48);background:rgba(182,239,103,.07)}
+.weapon-slot-label,.weapon-slot strong,.weapon-slot small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
+.weapon-slot-label{font:7px var(--mono);letter-spacing:.1em;color:#819087}
+.weapon-slot strong{margin-top:3px;color:#e3ebe1;font:700 15px/.95 var(--display);letter-spacing:.04em}
+.weapon-slot small{position:absolute;right:7px;top:8px;color:#7d8a80;font:7px var(--mono)}
+.weapon-slot.active .weapon-slot-label,.weapon-slot.active strong{color:var(--acid)}
+.weapon-slot.empty strong{color:#78857b;font:500 13px var(--mono)}
+.weapon-slot:disabled{opacity:.48;cursor:not-allowed}
+.attachments,.perks-view{display:flex;flex-direction:column;flex:1;min-height:0;padding-top:13px}
+.attachments>.section-label,.perks-view>.section-label{flex-shrink:0;margin-bottom:5px}
+#attachmentList,#perkList{min-height:0;overflow-y:auto;overscroll-behavior:contain;scrollbar-width:thin;scrollbar-color:#52624f transparent}
+.attachment-row{min-height:38px;height:auto;gap:8px}
+.attachment-name{flex:0 0 105px;display:flex;align-items:center;justify-content:space-between;gap:5px;font-size:7px}
+.attachment-name small{font:6px var(--mono);color:#69776d;white-space:nowrap}
+.attachment-options{min-width:0;overflow-x:auto;scrollbar-width:none}
+.attachment-options::-webkit-scrollbar{display:none}
+.attach-option{flex-shrink:0;white-space:nowrap}
+.attach-option:disabled{opacity:.32;cursor:not-allowed}
+.perks-view{gap:4px}
+#perkList{display:grid;grid-template-columns:1fr;gap:7px;padding:1px 5px 5px 1px}
+.perk-card{position:relative;min-height:76px;padding:12px 125px 12px 48px;display:flex;align-items:center;text-align:left;background:rgba(255,255,255,.018);border:1px solid rgba(220,240,220,.12);cursor:pointer;transition:background .15s,border-color .15s}
+.perk-card:hover,.perk-card.active{background:rgba(182,239,103,.06);border-color:rgba(182,239,103,.42)}
+.perk-check{position:absolute;left:14px;top:50%;transform:translateY(-50%);width:22px;height:22px;display:grid;place-items:center;border:1px solid rgba(220,240,220,.25);color:#8e9c91;font:14px var(--mono)}
+.perk-card.active .perk-check{border-color:var(--acid);background:var(--acid);color:#101812}
+.perk-copy strong,.perk-copy small{display:block}
+.perk-copy strong{font:700 19px/.95 var(--display);letter-spacing:.06em;color:#e6eee4}
+.perk-card.active .perk-copy strong{color:var(--acid)}
+.perk-copy small{margin-top:5px;color:#9aa79d;font-size:9px;line-height:1.45}
